import{_ as i,o as t,c as r,j as e,a,bu as l,ak as n,bv as s,bw as c,bx as d,by as u}from"./chunks/framework.gO8r5hi3.js";const C=JSON.parse('{"title":"Projet en classe : La caverne de la mort","description":"","frontmatter":{},"headers":[],"relativePath":"16_a_23_Projet_en_classe_La_caverne_de_la_mort.md","filePath":"16_a_23_Projet_en_classe_La_caverne_de_la_mort.md","lastUpdated":1775065760000}'),p={name:"16_a_23_Projet_en_classe_La_caverne_de_la_mort.md"};function m(h,o,g,v,b,f){return t(),r("div",null,[...o[0]||(o[0]=[e("h1",{id:"projet-en-classe-la-caverne-de-la-mort",tabindex:"-1"},[a("Projet en classe : La caverne de la mort "),e("a",{class:"header-anchor",href:"#projet-en-classe-la-caverne-de-la-mort","aria-label":"Permalink to “Projet en classe : La caverne de la mort”"},"​")],-1),e("p",null,[a('Dans les prochains cours (16 à 23), nous allons réaliser un jeu de type "platformer" où le joueur contrôle un personnage qui doit traverser un niveau et éviter des ennemis et des obstacles dangereux. Voici un '),e("a",{href:"https://h26-2j2.github.io/projet-caverne/",target:"_blank",rel:"noreferrer"},"exemple jouable"),a(" de ça qu'on va créer en classe.")],-1),e("p",null,[e("img",{src:l,alt:"Exemple - La caverne de la mort","width:":"","80%;":""})],-1),n('<h2 id="cours-17-deplacer-le-jouer-avec-la-physique" tabindex="-1">Cours 17 - Déplacer le jouer avec la physique <a class="header-anchor" href="#cours-17-deplacer-le-jouer-avec-la-physique" aria-label="Permalink to “Cours 17 - Déplacer le jouer avec la physique”">​</a></h2><p>On va implémenter ce déplacement en deux étapes : déplacement simple et avec des fonctionnalités extras.</p><h3 id="etape-1-deplacement-de-base" tabindex="-1">Étape 1 - Déplacement de base <a class="header-anchor" href="#etape-1-deplacement-de-base" aria-label="Permalink to “Étape 1 - Déplacement de base”">​</a></h3><ol><li>Ajouter un <strong>Rigidbody2D</strong> et un <strong>BoxCollider2D</strong> a l&#39;objet Personnage.</li><li>Dans <code>Start()</code>, on récupère une référence <code>rb</code> au <strong>Rigidbody2D</strong> avec <code>GetComponent&lt;&gt;()</code>.</li><li>Créer un nouveau script <code>DeplacementPlatformer.cs</code>.</li></ol><h4 id="configuration-de-controle" tabindex="-1">Configuration de contrôle <a class="header-anchor" href="#configuration-de-controle" aria-label="Permalink to “Configuration de contrôle”">​</a></h4><ol><li>Importer la bibliothèque <code>UnityEngine.InputSystem</code>.</li><li>Définir deux variables publiques <code>InputAction</code> nommées <code>entreeMarche</code> et <code>entreeSaut</code>.</li><li>On prépare les InputActions dans <code>OnEnable()</code> et <code>OnDisable()</code>.</li><li>Dans l&#39;<strong>Inspector</strong>, on ajoute des bindings : un positif/négatif pour <code>actionMarche</code> et un simple pour <code>actionSaut</code>.</li><li>Pour le mouvement et l&#39;input, on va synchroniser les inputs avec la physique. Pour faire ça, on va dans <strong>Edit &gt; ProjectSettings &gt; Input System Package &gt; Settings</strong> et on change <strong>Update Mode &gt; Process Events in Fixed Update</strong>. Pour plus de détails, voir <a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.19/manual/timing-optimize-fixed-update.html" target="_blank" rel="noreferrer">la documentation</a>.</li><li>Dans notre script, on va créer une fonction <code>FixedUpdate()</code> et, dans cette fonction, deux variables <code>float</code> locales : <code>axeMarche</code> avec la valeur de notre <code>actionMarche</code> et <code>intensiteMarche</code> avec la valeur absolue de cet axe (<code>Mathf.Abs(axeMarche)</code>).</li></ol><h4 id="appliquer-la-logique-de-la-marche" tabindex="-1">Appliquer la logique de la marche <a class="header-anchor" href="#appliquer-la-logique-de-la-marche" aria-label="Permalink to “Appliquer la logique de la marche”">​</a></h4><p>On veut avoir du mouvement de marche avec des accélerations pour donner un style plus fluide aux déplacements.</p><ol><li>Créer des champs publiques <code>float</code> pour <code>acccelerationMarche</code>, <code>vitesseXMax</code> et <code>vitesseXActuelle</code>.</li><li>On multiplie l&#39;<code>axeMarche</code> par l&#39;<code>accelerationMarche</code> et on somme au <code>rb.linearVelocityX</code>.</li><li>On limite la valeur de <code>rb.linearVelocityX</code> avec un <code>Mathf.Clamp()</code> et la <code>vitesseXMax</code>.</li><li>On garde la valeur de <code>rb.linearVelocityX</code> dans la variable <code>vitesseXActuelle</code> parce qu&#39;elle sera outil pour gérer les animations et le visuel du personnage.</li></ol><h4 id="appliquer-la-logique-du-saut" tabindex="-1">Appliquer la logique du saut <a class="header-anchor" href="#appliquer-la-logique-du-saut" aria-label="Permalink to “Appliquer la logique du saut”">​</a></h4><p>Pour le saut, on va commencer avec une implémentation qui ne limite pas láctivation du saut et où son hauteur est toujours la même.</p><ol><li>Changer le <code>Gravity Scale</code> du Rigidbody2D a <code>5f</code>.</li><li>Créer des champs publics <code>float</code> pour <code>accelerationSaut</code> et<code>vitesseYMax</code>.</li><li>Si <code>actionSaut.WasPressedThisFrame()</code>, on va commencer le saut, donc le <code>tempsSaut = 0f</code>. <ol><li>On applique l&#39;impulsion vers le haut avec la méthode <code>rb.AddForce(Vector2.up * impulsionSaut, ForceMode2D.Impulse)</code>. Le <code>Vector2.up</code> défine la direction et l&#39;<code>impulsionSaut</code> l&#39;intensité de la force. L&#39;argument <code>ForceMode2D.Impulse</code> applique cette accélération de façon immédiate.</li><li>Pour éviter des déplacements extrêmes, on limite la valeur de <code>rb.linearVelocityY</code> avec un <code>Mathf.Clamp()</code> et la <code>vitesseYMax</code>.</li></ol></li></ol><h4 id="configuration-exemple-pour-l-etape-1" tabindex="-1">Configuration exemple -pour l&#39;étape 1 <a class="header-anchor" href="#configuration-exemple-pour-l-etape-1" aria-label="Permalink to “Configuration exemple -pour l&#39;étape 1”">​</a></h4><p>Voici quelques valeurs intéressantes pour la configuration du composant :</p><p><img src="'+s+'" alt="alt text"></p><h3 id="etape-2-detection-du-sol-et-saut-variable" tabindex="-1">Étape 2 - Détection du sol et saut variable <a class="header-anchor" href="#etape-2-detection-du-sol-et-saut-variable" aria-label="Permalink to “Étape 2 - Détection du sol et saut variable”">​</a></h3><h4 id="modifier-la-logique-de-la-marche" tabindex="-1">Modifier la logique de la marche <a class="header-anchor" href="#modifier-la-logique-de-la-marche" aria-label="Permalink to “Modifier la logique de la marche”">​</a></h4><p>On veut avoir du mouvement de marche avec des accélerations pour donner un style plus fluide aux déplacements.</p><ol><li>Changer le <code>Linear Damping</code> du Rigidbody2D a <code>0f</code>.</li><li>Créer un champs publiques <code>float</code> pour <code>ralentissementMarche</code>.</li><li>Pour <strong>ralentir la marche</strong>:</li><li>Si on n&#39;as pas d&#39;intensité de marche (<code>intensiteMarche &lt;= 0.01f</code>), on ralentisse la vitesse X du <code>rb</code> avec une interpolation vers 0f (<code>Mathf.Lerp(rb.linearVelocityX, 0, ralentissementMarche * Time.fixedDeltaTime)</code>).</li></ol><h4 id="modifier-la-logique-du-saut" tabindex="-1">Modifier la logique du saut <a class="header-anchor" href="#modifier-la-logique-du-saut" aria-label="Permalink to “Modifier la logique du saut”">​</a></h4><p>Pour le saut, on veut le modifier pour qu&#39;il soit activé seulement quand le personnage est au sol. On veut aussi que l&#39;impulsion du saut a une durée maximale : ça nous permet d&#39;avoir un saut d&#39;hauteur variable selon le temps qu&#39;on enfonce la touche, en lieu d&#39;une hauteur fixe.</p><ol><li>Créer des champs publics <code>float</code> pour <code>tempsSaut</code>, <code>dureeImpulsionSaut</code>, <code>vitesseYMax</code>, un champs <code>LayerMask calquesSol</code> et un champs <code>bool estAuSol</code>.</li><li>Pour faire la <strong>détection du sol</strong>: <ol><li>On va tester si le personnage est au sol avec la méthode <code>Physics2D.Raycast(rb.position, Vector2.down, 1f, calquesSol)</code> qui lance un rayon d&#39;un mètre de longueur à partir de son pivot vers en bas. Les objets hors les <code>calquesSol</code> vont être ignorés.</li><li>On garde le résultat dans une variable locale <code>RaycastHit2D hit</code>. <ol><li>Si <code>hit.collider</code> est nul, le rayon n’a pas touché d’objets dans les calques du sol.</li><li>Si <code>hit.collider</code> n&#39;est pas nul, le rayon a touché le sol.</li><li>On garde le résultat de ces conditions dans la variable <code>estAuSol</code>.</li></ol></li></ol></li><li>Pour créer <strong>la hauteur variable</strong>, on va ajouter deux <code>if</code> et modifier le <code>if</code> déjà existant: <ol><li>Si <code>actionSaut.WasPressedThisFrame() &amp;&amp; estAuSol</code>, on va commencer le saut, donc le <code>tempsSaut = 0f</code>.</li><li>Dans le if du <code>actionSaut.IsPressed()</code>, on augmente le <code>tempsSaut</code> pour montrer que plus de temps enfoncé c&#39;est passé.</li><li>Si <code>actionSaut.WasReleasedThisFrame()</code>, le bouton est relâché, donc on change le <code>tempsSaut</code> à l&#39;infini pour éviter que l&#39;impulsion soit appliquée.</li></ol></li></ol><h4 id="configuration-exemple-pour-l-etape-2" tabindex="-1">Configuration exemple pour l&#39;étape 2 <a class="header-anchor" href="#configuration-exemple-pour-l-etape-2" aria-label="Permalink to “Configuration exemple pour l&#39;étape 2”">​</a></h4><p><img src="'+c+'" alt="Config étape 2"></p><h2 id="cours-18-controle-de-camera-avec-cinemachine" tabindex="-1">Cours 18 - Contrôle de caméra avec Cinemachine <a class="header-anchor" href="#cours-18-controle-de-camera-avec-cinemachine" aria-label="Permalink to “Cours 18 - Contrôle de caméra avec Cinemachine”">​</a></h2><h3 id="configuration-de-base-2d-camera" tabindex="-1">Configuration de base : 2D Camera <a class="header-anchor" href="#configuration-de-base-2d-camera" aria-label="Permalink to “Configuration de base : 2D Camera”">​</a></h3><ol><li>Si le package <strong>Cinemachine</strong> n&#39;est pas installé, aller sur <em>Window &gt; PackageManager &gt;Unity Registry</em> et l&#39;installer.</li><li>On ajoute un composant <strong>Cinemachine Brain</strong> à la <strong>Main Camera</strong> de la scène.</li><li>On crée un nouvel objet dans la scène avec <em>GameObject &gt; Cinemachine &gt; Targeted Cameras &gt; 2D Camera</em>.</li><li>Dans le nouvel objet CinemachineCamera, on change la propriété <code>Tracking Target</code> à notre objet de Personnage.</li><li>On change la propriété <code>Lens</code> à 5 pour répliquer la taille de la caméra défaut.</li></ol><h3 id="composition-dynamique" tabindex="-1">Composition dynamique <a class="header-anchor" href="#composition-dynamique" aria-label="Permalink to “Composition dynamique”">​</a></h3><p>Le composant <strong>Cinemachine Position Composer</strong> permet d&#39;encadrer l&#39;objet cible (<code>Tracking Target</code>) dynamiquement, avec des <strong>zones mortes</strong> (où la caméra ne suive pas la cible), <strong>anticipation</strong> (Lookahead, quand la caméra suit une estimation de la position future de la cible) et des <strong>limites de cadre</strong>.</p><p><img src="'+d+'" alt="Configuration du Position Composer"></p><h3 id="limites-de-niveau-pour-la-camera" tabindex="-1">Limites de niveau pour la caméra <a class="header-anchor" href="#limites-de-niveau-pour-la-camera" aria-label="Permalink to “Limites de niveau pour la caméra”">​</a></h3><p>On peut aussi définir des limites sur l&#39;espace général de la scène. Les étapes pour configurer des limites sont :</p><ol><li>On clique sur le bouton <em>Add Extension</em> de notre <strong>CinechineCamera</strong> et on ajoute un composant <strong>Cinemachine Confiner2D</strong>.</li><li>On ajoute un nouvel objet vide dans la scène nommé <strong>LimitesCameraNiveau</strong> avec un <strong>BoxCollider2D</strong>. Éditer la forme du collider pour délimiter l&#39;espace de la caméra. Activer l&#39;option <code>IsTrigger</code>.</li><li>On connecte cet objet <strong>LimitesCameraNiveau</strong> à la propriété <code>Bounding Shape 2D</code> du <strong>Confiner2D</strong>.</li></ol><p><img src="'+u+'" alt="Configuration du Confiner2D"></p><h2 id="cours-19-gestion-d-animations-multiples-avec-animator-pt-1" tabindex="-1">Cours 19 - Gestion d&#39;animations multiples avec Animator pt.1 <a class="header-anchor" href="#cours-19-gestion-d-animations-multiples-avec-animator-pt-1" aria-label="Permalink to “Cours 19 - Gestion d&#39;animations multiples avec Animator pt.1”">​</a></h2><p>À venir.</p><h2 id="cours-20-gestion-d-animations-multiples-avec-animator-pt-2" tabindex="-1">Cours 20 - Gestion d&#39;animations multiples avec Animator pt.2 <a class="header-anchor" href="#cours-20-gestion-d-animations-multiples-avec-animator-pt-2" aria-label="Permalink to “Cours 20 - Gestion d&#39;animations multiples avec Animator pt.2”">​</a></h2><p>À venir.</p><h2 id="cours-21-instanciation-de-projectiles" tabindex="-1">Cours 21 - Instanciation de projectiles <a class="header-anchor" href="#cours-21-instanciation-de-projectiles" aria-label="Permalink to “Cours 21 - Instanciation de projectiles”">​</a></h2><p>À venir.</p><h2 id="cours-22-gestion-d-ennemis-et-listes" tabindex="-1">Cours 22 - Gestion d&#39;ennemis et listes <a class="header-anchor" href="#cours-22-gestion-d-ennemis-et-listes" aria-label="Permalink to “Cours 22 - Gestion d&#39;ennemis et listes”">​</a></h2><p>À venir.</p><h2 id="cours-23-post-processing-et-lumieres-2d" tabindex="-1">Cours 23 - Post processing et lumières 2D <a class="header-anchor" href="#cours-23-post-processing-et-lumieres-2d" aria-label="Permalink to “Cours 23 - Post processing et lumières 2D”">​</a></h2><p>À venir.</p>',44)])])}const x=i(p,[["render",m]]);export{C as __pageData,x as default};
